##  The Heist: A Simple Database Breached Script

This is a basic script demonstrating a potential scenario of a database breach, focusing on the potential targets of personal information.

```python
import random

class Target:
  """Represents a company and its potential data breach targets."""
  def __init__(self, company_name, data_types):
    self.company_name = company_name
    self.data_types = data_types

  def generate_data(self):
    """Randomly generates some personal data associated with the target."""
    data = {
        "email": f"{random.randint(1,10000)}.{random.randint(1,1000)}@{random.randint(1,1000)}",
        "name": f"John {random.randint(1,100)} {random.randint(1,100)}",
        "phone_number": f"{random.randint(1000,9999)}-{random.randint(1,999)}"
    }
    return data

def breach_check(target):
  """Simulates a data breach based on the target's data types."""
  for data_type in target.data_types:
    print(f"Checking data type: {data_type}")
    if data_type == "email":
      print(f"Breached data: Email for {target.company_name} - {target.generate_data()}")
    elif data_type == "name":
      print(f"Breached data: Name for {target.company_name} - {target.generate_data()}")
    elif data_type == "phone_number":
      print(f"Breached data: Phone number for {target.company_name} - {target.generate_data()}")
    else:
      print(f"Breached data: Unknown data type for {target.company_name}")

